import React, { useEffect, useState } from "react";
import { io } from "socket.io-client";
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Tooltip,
    Legend,
} from "chart.js";
import { Line } from "react-chartjs-2";

ChartJS.register(
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Tooltip,
    Legend
);

const API_URL =
    process.env.REACT_APP_API_URL ||
    "http://localhost:5005";

const MAX_POINTS = 20;


function Dashboard() {
    const [alerts, setAlerts] = useState([]);
    const [connected, setConnected] = useState(false);
    const [loading, setLoading] = useState(true);


    // =====================================
    // LOAD HISTORY + SOCKET.IO
    // =====================================

    useEffect(() => {
        const socket = io(API_URL, {
            transports: ["websocket", "polling"],
            withCredentials: true,
        });


        // =================================
        // SOCKET CONNECT
        // =================================

        socket.on("connect", () => {
            console.log(
                "Dashboard Socket.IO connected:",
                socket.id
            );

            setConnected(true);
        });


        // =================================
        // SOCKET DISCONNECT
        // =================================

        socket.on("disconnect", (reason) => {
            console.log(
                "Dashboard Socket.IO disconnected:",
                reason
            );

            setConnected(false);
        });


        // =================================
        // REAL-TIME ALERT
        // =================================

        socket.on("alert", (alert) => {
            console.log(
                "Dashboard received alert:",
                alert
            );

            setAlerts((current) => {
                const key =
                    alert._id ||
                    `${alert.productID}-${alert.timestamp}`;

                const exists = current.some(
                    (item) => {
                        const itemKey =
                            item._id ||
                            `${item.productID}-${item.timestamp}`;

                        return itemKey === key;
                    }
                );

                if (exists) {
                    return current;
                }

                return [
                    ...current,
                    alert,
                ].slice(-MAX_POINTS);
            });
        });


        // =================================
        // LOAD DATABASE HISTORY
        // =================================

        fetch(`${API_URL}/api/alerts`)
            .then((response) => {
                if (!response.ok) {
                    throw new Error(
                        `HTTP ${response.status}`
                    );
                }

                return response.json();
            })
            .then((history) => {
                console.log(
                    "Dashboard alert history:",
                    history
                );

                setAlerts((current) => {
                    // Combine database history with
                    // alerts that arrived through Socket.IO
                    const combined = [
                        ...history,
                        ...current,
                    ];

                    // Remove duplicates
                    const unique = Array.from(
                        new Map(
                            combined.map((item) => {
                                const key =
                                    item._id ||
                                    `${item.productID}-${item.timestamp}`;

                                return [
                                    key,
                                    item,
                                ];
                            })
                        ).values()
                    );

                    // Oldest -> newest
                    unique.sort(
                        (a, b) =>
                            new Date(a.timestamp) -
                            new Date(b.timestamp)
                    );

                    return unique.slice(
                        -MAX_POINTS
                    );
                });

                setLoading(false);
            })
            .catch((error) => {
                console.error(
                    "Failed to load alert history:",
                    error
                );

                setLoading(false);
            });


        // =================================
        // CLEANUP
        // =================================

        return () => {
            socket.disconnect();
        };
    }, []);


    // =====================================
    // CHART DATA
    // =====================================

    const chartData = {
        labels: alerts.map(
            (item) => item.productID
        ),

        datasets: [
            {
                label: "Torque (Nm)",

                data: alerts.map(
                    (item) => item.torque
                ),

                tension: 0.3,

                borderWidth: 2,

                pointRadius: 5,
            },

            {
                label: "Tool Wear",

                data: alerts.map(
                    (item) => item.toolWear
                ),

                tension: 0.3,

                borderWidth: 2,

                pointRadius: 5,
            },
        ],
    };


    // =====================================
    // CHART OPTIONS
    // =====================================

    const chartOptions = {
        responsive: true,

        maintainAspectRatio: false,

        plugins: {
            legend: {
                position: "top",
            },
        },

        scales: {
            y: {
                beginAtZero: false,
            },
        },
    };


    // =====================================
    // RENDER
    // =====================================

    return (
        <div
            style={{
                minHeight: "100vh",
                padding: "40px",
                background: "#071018",
                color: "#ffffff",
            }}
        >

            {/* HEADER */}

            <div
                style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    marginBottom: "30px",
                }}
            >
                <div>

                    <div
                        style={{
                            color: "#45e0ca",
                            fontSize: "13px",
                            letterSpacing: "3px",
                            marginBottom: "10px",
                        }}
                    >
                        EDGE ANALYTICS / LIVE OPERATIONS
                    </div>

                    <h1
                        style={{
                            margin: 0,
                            fontSize: "42px",
                        }}
                    >
                        Predictive Maintenance Environment
                    </h1>

                </div>


                {/* CONNECTION STATUS */}

                <div
                    style={{
                        display: "flex",
                        alignItems: "center",
                        gap: "10px",
                    }}
                >

                    <span
                        style={{
                            width: "9px",
                            height: "9px",
                            borderRadius: "50%",
                            background: connected
                                ? "#45e0ca"
                                : "#ff5555",
                            display: "inline-block",
                        }}
                    />

                    <span
                        style={{
                            fontSize: "13px",
                            letterSpacing: "1px",
                        }}
                    >
                        {connected
                            ? "STREAM ACTIVE"
                            : "STREAM OFFLINE"}
                    </span>

                </div>

            </div>


            {/* MAIN GRID */}

            <div
                style={{
                    display: "grid",
                    gridTemplateColumns:
                        "minmax(0, 2fr) minmax(350px, 1fr)",
                    gap: "22px",
                }}
            >

                {/* =========================
                    TELEMETRY
                ========================= */}

                <div
                    style={{
                        border: "1px solid #203541",
                        background: "#0d1a24",
                        minHeight: "600px",
                    }}
                >

                    <div
                        style={{
                            padding: "22px 26px",
                            borderBottom:
                                "1px solid #203541",
                            display: "flex",
                            justifyContent:
                                "space-between",
                        }}
                    >

                        <div>

                            <div
                                style={{
                                    color: "#45e0ca",
                                    fontSize: "12px",
                                    letterSpacing: "2px",
                                    marginBottom: "8px",
                                }}
                            >
                                TELEMETRY
                            </div>

                            <h2
                                style={{
                                    margin: 0,
                                    fontSize: "22px",
                                }}
                            >
                                Machine signal history
                            </h2>

                        </div>


                        <div
                            style={{
                                color: "#9aaebd",
                                fontSize: "13px",
                            }}
                        >
                            {alerts.length} POINTS
                        </div>

                    </div>


                    <div
                        style={{
                            height: "500px",
                            padding: "20px",
                        }}
                    >

                        {loading ? (
                            <div>
                                Loading machine data...
                            </div>
                        ) : alerts.length === 0 ? (
                            <div>
                                No machine data available.
                            </div>
                        ) : (
                            <Line
                                data={chartData}
                                options={chartOptions}
                            />
                        )}

                    </div>

                </div>


                {/* =========================
                    ALERTS
                ========================= */}

                <AlertPanel alerts={alerts} />

            </div>

        </div>
    );
}


// =========================================
// ALERT PANEL
// =========================================

function AlertPanel({ alerts }) {

    const recentAlerts = [...alerts]
        .sort(
            (a, b) =>
                new Date(b.timestamp) -
                new Date(a.timestamp)
        )
        .slice(0, 50);


    return (
        <div
            style={{
                border: "1px solid #203541",
                background: "#0d1a24",
                minHeight: "600px",
            }}
        >

            <div
                style={{
                    padding: "22px 26px",
                    borderBottom:
                        "1px solid #203541",
                    display: "flex",
                    justifyContent:
                        "space-between",
                }}
            >

                <div>

                    <div
                        style={{
                            color: "#45e0ca",
                            fontSize: "12px",
                            letterSpacing: "2px",
                            marginBottom: "8px",
                        }}
                    >
                        INCIDENT LOG
                    </div>

                    <h2
                        style={{
                            margin: 0,
                            fontSize: "22px",
                        }}
                    >
                        Recent alerts
                    </h2>

                </div>


                <div
                    style={{
                        color: "#9aaebd",
                        fontSize: "13px",
                    }}
                >
                    {recentAlerts.length} EVENTS
                </div>

            </div>


            <div
                style={{
                    padding: "0 26px",
                    maxHeight: "520px",
                    overflowY: "auto",
                }}
            >

                {recentAlerts.length === 0 ? (

                    <div
                        style={{
                            padding: "30px 0",
                            color: "#8ea2b1",
                        }}
                    >
                        No alerts available.
                    </div>

                ) : (

                    recentAlerts.map((alert) => (

                        <div
                            key={
                                alert._id ||
                                `${alert.productID}-${alert.timestamp}`
                            }
                            style={{
                                padding:
                                    "22px 0",
                                borderBottom:
                                    "1px solid #203541",
                            }}
                        >

                            <div
                                style={{
                                    display: "flex",
                                    justifyContent:
                                        "space-between",
                                }}
                            >

                                <strong
                                    style={{
                                        fontSize: "16px",
                                    }}
                                >
                                    {alert.productID}
                                </strong>

                                <span
                                    style={{
                                        color: "#8ea2b1",
                                        fontSize:
                                            "12px",
                                    }}
                                >
                                    {new Date(
                                        alert.timestamp
                                    ).toLocaleTimeString()}
                                </span>

                            </div>


                            <div
                                style={{
                                    marginTop:
                                        "8px",
                                    color:
                                        alert.status
                                            ?.includes(
                                                "CRITICAL"
                                            )
                                            ? "#ff5c6c"
                                            : "#45e0ca",
                                    fontWeight:
                                        "bold",
                                    fontSize:
                                        "13px",
                                }}
                            >
                                {alert.status}
                            </div>


                            <div
                                style={{
                                    marginTop:
                                        "12px",
                                    color: "#8ea2b1",
                                    fontSize:
                                        "13px",
                                }}
                            >
                                Torque:{" "}
                                {alert.torque} Nm
                                {" / "}
                                Wear:{" "}
                                {alert.toolWear}
                                {" / "}
                                RPM:{" "}
                                {alert.rotationalSpeed}
                            </div>

                        </div>

                    ))

                )}

            </div>

        </div>
    );
}


export default Dashboard;
